// e2e/helpers/TableHelper.ts
// Generated by e2e-flow skill (Phase 1). Maps to DataTable in your design system.
import { expect } from "@playwright/test"
import type { Locator, Page } from "@playwright/test"

export class TableHelper {
  constructor(private readonly page: Page) {}

  /** 특정 텍스트가 포함된 행을 반환. */
  getRowByText(rowText: string | RegExp, opts?: { within?: Locator }): Locator {
    const root = opts?.within ?? this.page
    return root.getByRole("row").filter({ hasText: rowText })
  }

  /** 행 내부의 액션 버튼 클릭. */
  async clickRowAction(
    rowText: string | RegExp,
    actionName: string | RegExp,
    opts?: { within?: Locator }
  ): Promise<void> {
    const row = this.getRowByText(rowText, opts)
    await expect(row).toBeVisible()
    await row.getByRole("button", { name: actionName }).click()
  }

  /** 데이터 행 개수 검증 (header row 제외). */
  async expectRowCount(
    count: number,
    opts?: { within?: Locator }
  ): Promise<void> {
    const root = opts?.within ?? this.page
    await expect(root.getByRole("row")).toHaveCount(count + 1)
  }

  /** 특정 행 존재 검증. */
  async expectRowExists(
    rowText: string | RegExp,
    opts?: { within?: Locator }
  ): Promise<void> {
    await expect(this.getRowByText(rowText, opts)).toBeVisible()
  }
}
